changeSet.sql:
ALTER TABLE modeling_plan_execution_binding DROP CONSTRAINT ck_model_plan_execution_binding_payload; UPDATE modeling_plan_execution_binding SET deployment_status = CASE WHEN deployed_checksum = desired_deployment_checksum THEN 'ACTIVE' ELSE 'STALE' END WHERE deployment_status = 'DEPLOYED'; ALTER TABLE modeling_plan_execution_binding ADD CONSTRAINT ck_model_plan_execution_binding_payload CHECK ( version > 0 AND ( ( schedule_mode = 'MANUAL_ONLY' AND cron_expression IS NULL AND timezone IS NULL ) OR ( schedule_mode = 'CRON_ENABLED' AND nullif(btrim(cron_expression), '') IS NOT NULL AND nullif(btrim(timezone), '') IS NOT NULL ) ) AND desired_scope_checksum ~ '^[0-9a-f]{64}$' AND desired_deployment_checksum ~ '^[0-9a-f]{64}$' AND deployment_status IN ( 'DEPLOYING', 'ACTIVE', 'STALE', 'DISABLED', 'FAILED', 'UNKNOWN' ) AND ( deployed_checksum IS NULL OR deployed_checksum ~ '^[0-9a-f]{64}$' ) );
ALTER TABLE modeling_pipeline_run DROP CONSTRAINT ck_modeling_pipeline_run_candidate_build; ALTER TABLE modeling_pipeline_run ADD CONSTRAINT ck_modeling_pipeline_run_candidate_build CHECK ( ( release_candidate_id IS NULL AND release_candidate_entry_id IS NULL AND release_candidate_version IS NULL AND pipeline_run_group_id IS NULL AND implementation_revision IS NULL AND implementation_checksum IS NULL AND environment IS NULL AND run_purpose IS NULL AND attempt IS NULL AND artifact_bundle_checksum IS NULL AND ( scoped_bundle_checksum IS NULL OR scoped_bundle_checksum ~ '^[0-9a-f]{64}$' ) AND dbt_invocation_id IS NULL AND execution_binding_id IS NULL AND binding_version IS NULL AND trigger_type IS NULL AND logical_date IS NULL AND scope_checksum IS NULL AND operational_active_claim_key IS NULL ) OR ( release_candidate_id IS NOT NULL AND release_candidate_entry_id IS NOT NULL AND release_candidate_version > 0 AND pipeline_run_group_id IS NOT NULL AND implementation_revision > 0 AND implementation_checksum ~ '^[0-9a-f]{64}$' AND btrim(environment) <> '' AND environment = btrim(environment) AND run_purpose = 'RELEASE_BUILD' AND attempt > 0 AND artifact_bundle_checksum ~ '^[0-9a-f]{64}$' AND ( scoped_bundle_checksum IS NULL OR scoped_bundle_checksum ~ '^[0-9a-f]{64}$' ) AND dbt_invocation_id IS NOT NULL AND btrim(airflow_dag_id) <> '' AND btrim(airflow_run_id) <> '' AND btrim(dbt_selector) <> '' AND btrim(target) <> '' AND execution_binding_id IS NULL AND binding_version IS NULL AND trigger_type IS NULL AND logical_date IS NULL AND scope_checksum IS NULL AND operational_active_claim_key IS NULL ) OR ( release_candidate_id IS NULL AND release_candidate_entry_id IS NULL AND release_candidate_version IS NULL AND pipeline_run_group_id IS NOT NULL AND implementation_revision > 0 AND implementation_checksum ~ '^[0-9a-f]{64}$' AND btrim(environment) <> '' AND environment = btrim(environment) AND run_purpose = 'OPERATIONAL_RUN' AND attempt > 0 AND artifact_bundle_checksum ~ '^[0-9a-f]{64}$' AND ( scoped_bundle_checksum IS NULL OR scoped_bundle_checksum ~ '^[0-9a-f]{64}$' ) AND dbt_invocation_id IS NOT NULL AND btrim(airflow_dag_id) <> '' AND btrim(airflow_run_id) <> '' AND btrim(dbt_selector) <> '' AND btrim(target) <> '' AND execution_binding_id IS NOT NULL AND binding_version > 0 AND trigger_type IN ('MANUAL', 'CRON') AND ( (trigger_type = 'MANUAL' AND logical_date IS NULL) OR (trigger_type = 'CRON' AND logical_date IS NOT NULL) ) AND scope_checksum ~ '^[0-9a-f]{64}$' AND ( operational_active_claim_key IS NULL OR operational_active_claim_key ~ '^[0-9a-f]{64}$' ) ) );
CREATE UNIQUE INDEX uk_pipeline_run_operational_active_claim ON modeling_pipeline_run (operational_active_claim_key) WHERE operational_active_claim_key IS NOT NULL;
CREATE UNIQUE INDEX uk_pipeline_run_binding_dag_model ON modeling_pipeline_run ( tenant_id, execution_binding_id, airflow_run_id, model_spec_id ) WHERE run_purpose = 'OPERATIONAL_RUN';
CREATE INDEX idx_pipeline_run_binding_history ON modeling_pipeline_run ( tenant_id, execution_binding_id, created_date DESC ) WHERE run_purpose = 'OPERATIONAL_RUN';
ALTER TABLE modeling_physical_relation_observation DROP CONSTRAINT ck_physical_relation_observation; ALTER TABLE modeling_physical_relation_observation ADD CONSTRAINT ck_physical_relation_observation CHECK ( btrim(tenant_id) <> '' AND ( ( run_purpose = 'RELEASE_BUILD' AND release_candidate_id IS NOT NULL AND release_candidate_version > 0 AND execution_binding_id IS NULL AND binding_version IS NULL ) OR ( run_purpose = 'OPERATIONAL_RUN' AND release_candidate_id IS NULL AND release_candidate_version IS NULL AND execution_binding_id IS NOT NULL AND binding_version > 0 ) ) AND model_revision > 0 AND implementation_revision > 0 AND observation_attempt > 0 AND model_checksum ~ '^[0-9a-f]{64}$' AND implementation_checksum ~ '^[0-9a-f]{64}$' AND scoped_bundle_checksum ~ '^[0-9a-f]{64}$' AND credential_version_ref ~ '^sha256:[0-9a-f]{64}$' AND expected_columns_checksum ~ '^[0-9a-f]{64}$' AND adapter = 'postgres' AND schema_name ~ '^[A-Za-z_][A-Za-z0-9_]{0,127}$' AND identifier ~ '^[A-Za-z_][A-Za-z0-9_]{0,127}$' AND expected_type IN ( 'TABLE', 'VIEW', 'MATERIALIZED_VIEW' ) AND column_count >= 0 AND ( ( relation_exists AND actual_type IN ( 'TABLE', 'VIEW', 'MATERIALIZED_VIEW' ) AND columns_checksum ~ '^[0-9a-f]{64}$' AND actual_columns IS NOT NULL AND metadata_checksum ~ '^[0-9a-f]{64}$' AND column_count > 0 ) OR ( NOT relation_exists AND actual_type IS NULL AND columns_checksum IS NULL AND actual_columns IS NULL AND metadata_checksum IS NULL AND column_count = 0 ) ) AND ( ( verified AND relation_exists AND error_code IS NULL ) OR ( NOT verified AND nullif(btrim(error_code), '') IS NOT NULL ) ) );
ALTER TABLE modeling_operational_run_dispatch ADD CONSTRAINT ck_modeling_operational_run_dispatch CHECK ( btrim(tenant_id) <> '' AND binding_version > 0 AND trigger_type IN ('MANUAL', 'CRON') AND ( (trigger_type = 'MANUAL' AND logical_date IS NULL) OR (trigger_type = 'CRON' AND logical_date IS NOT NULL) ) AND btrim(execution_target_key) <> '' AND btrim(target_name) <> '' AND btrim(airflow_dag_id) <> '' AND btrim(airflow_run_id) <> '' AND scope_checksum ~ '^[0-9a-f]{64}$' AND ( project_bundle_checksum IS NULL OR project_bundle_checksum ~ '^[0-9a-f]{64}$' ) AND ( ( runtime_token_digest IS NULL AND runtime_token_expires_at IS NULL ) OR ( runtime_token_digest ~ '^sha256:[0-9a-f]{64}$' AND runtime_token_expires_at IS NOT NULL ) ) AND status IN ( 'PENDING', 'CLAIMED', 'SUBMITTED', 'UNKNOWN', 'COMPLETED', 'FAILED', 'BLOCKED' ) AND dispatch_attempts >= 0 AND ( (profile_lease_id IS NULL AND runtime_consumed_at IS NULL) OR (profile_lease_id IS NOT NULL AND runtime_consumed_at IS NOT NULL) ) );
CREATE UNIQUE INDEX uk_operational_dispatch_binding_dag_run ON modeling_operational_run_dispatch ( tenant_id, binding_id, airflow_run_id );
CREATE UNIQUE INDEX uk_operational_dispatch_runtime_token ON modeling_operational_run_dispatch (runtime_token_digest) WHERE runtime_token_digest IS NOT NULL;
CREATE INDEX idx_operational_dispatch_ready ON modeling_operational_run_dispatch ( status, next_attempt_at, created_at, id ) WHERE status IN ('PENDING', 'CLAIMED', 'UNKNOWN');

rollback.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
          FROM modeling_pipeline_run
         WHERE run_purpose = 'OPERATIONAL_RUN'
    ) OR EXISTS (
        SELECT 1 FROM modeling_operational_run_dispatch
    ) OR EXISTS (
        SELECT 1
          FROM modeling_plan_execution_binding
         WHERE schedule_mode <> 'MANUAL_ONLY'
            OR deployment_status IN (
                'STALE', 'DISABLED', 'UNKNOWN'
            )
    ) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_OPERATIONAL_RUN_DATA_EXISTS';
    END IF;
END $$;

ALTER TABLE modeling_physical_relation_observation
    DROP CONSTRAINT ck_physical_relation_observation;
ALTER TABLE modeling_pipeline_run
    DROP CONSTRAINT ck_modeling_pipeline_run_candidate_build;

DROP INDEX IF EXISTS idx_pipeline_run_binding_history;
DROP INDEX IF EXISTS uk_pipeline_run_binding_dag_model;
DROP INDEX IF EXISTS uk_pipeline_run_operational_active_claim;

ALTER TABLE modeling_pipeline_run ADD CONSTRAINT ck_modeling_pipeline_run_candidate_build CHECK ( ( release_candidate_id IS NULL AND release_candidate_entry_id IS NULL AND release_candidate_version IS NULL AND pipeline_run_group_id IS NULL AND implementation_revision IS NULL AND implementation_checksum IS NULL AND environment IS NULL AND run_purpose IS NULL AND attempt IS NULL AND artifact_bundle_checksum IS NULL AND scoped_bundle_checksum IS NULL AND dbt_invocation_id IS NULL ) OR ( release_candidate_id IS NOT NULL AND release_candidate_entry_id IS NOT NULL AND release_candidate_version > 0 AND pipeline_run_group_id IS NOT NULL AND implementation_revision > 0 AND implementation_checksum ~ '^[0-9a-f]{64}$' AND btrim(environment) <> '' AND environment = btrim(environment) AND run_purpose IN ('RELEASE_BUILD', 'OPERATIONAL_RUN') AND attempt > 0 AND artifact_bundle_checksum ~ '^[0-9a-f]{64}$' AND ( scoped_bundle_checksum IS NULL OR scoped_bundle_checksum ~ '^[0-9a-f]{64}$' ) AND dbt_invocation_id IS NOT NULL AND btrim(airflow_dag_id) <> '' AND btrim(airflow_run_id) <> '' AND btrim(dbt_selector) <> '' AND btrim(target) <> '' ) );
ALTER TABLE modeling_physical_relation_observation ADD CONSTRAINT ck_physical_relation_observation CHECK ( btrim(tenant_id) <> '' AND release_candidate_version > 0 AND model_revision > 0 AND implementation_revision > 0 AND observation_attempt > 0 AND model_checksum ~ '^[0-9a-f]{64}$' AND implementation_checksum ~ '^[0-9a-f]{64}$' AND scoped_bundle_checksum ~ '^[0-9a-f]{64}$' AND credential_version_ref ~ '^sha256:[0-9a-f]{64}$' AND expected_columns_checksum ~ '^[0-9a-f]{64}$' AND adapter = 'postgres' AND schema_name ~ '^[A-Za-z_][A-Za-z0-9_]{0,127}$' AND identifier ~ '^[A-Za-z_][A-Za-z0-9_]{0,127}$' AND expected_type IN ( 'TABLE', 'VIEW', 'MATERIALIZED_VIEW' ) AND column_count >= 0 AND ( ( relation_exists AND actual_type IN ( 'TABLE', 'VIEW', 'MATERIALIZED_VIEW' ) AND columns_checksum ~ '^[0-9a-f]{64}$' AND actual_columns IS NOT NULL AND metadata_checksum ~ '^[0-9a-f]{64}$' AND column_count > 0 ) OR ( NOT relation_exists AND actual_type IS NULL AND columns_checksum IS NULL AND actual_columns IS NULL AND metadata_checksum IS NULL AND column_count = 0 ) ) AND ( ( verified AND relation_exists AND error_code IS NULL ) OR ( NOT verified AND nullif(btrim(error_code), '') IS NOT NULL ) ) );
ALTER TABLE modeling_plan_execution_binding DROP CONSTRAINT ck_model_plan_execution_binding_payload; UPDATE modeling_plan_execution_binding SET deployment_status = 'DEPLOYED' WHERE deployment_status = 'ACTIVE'; ALTER TABLE modeling_plan_execution_binding ADD CONSTRAINT ck_model_plan_execution_binding_payload CHECK ( version > 0 AND schedule_mode = 'MANUAL_ONLY' AND cron_expression IS NULL AND timezone IS NULL AND desired_scope_checksum ~ '^[0-9a-f]{64}$' AND desired_deployment_checksum ~ '^[0-9a-f]{64}$' AND deployment_status IN ('DEPLOYING', 'DEPLOYED', 'FAILED') AND ( deployed_checksum IS NULL OR deployed_checksum ~ '^[0-9a-f]{64}$' ) );
